package operadores;

public class Asignacion {

	public static void main(String[] args) {
		// TODO Auto-generated method stub

		//+=, -=, *=, /=
		
		int x = 10;
		System.out.println("x = " + x);
		x = x + 1;
		System.out.println("x = " + x);
		x+=1;
		x-=1;
		x*=2;
		x/=2;
		System.out.println("x = " + x);
		
			
	}

}
